INSERT INTO public.mcq_banks (
  subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order
)
SELECT
  s.subject, s.chapter, s.chapter_title, s.section, s.language, s.question, s.choices, s.answer_index, s.source, s.sort_order
FROM seed AS s
WHERE NOT EXISTS (
  SELECT 1
  FROM public.mcq_banks AS existing
  WHERE existing.subject = s.subject
    AND existing.chapter = s.chapter
    AND existing.language = s.language
    AND existing.question = s.question
);
